std::string ConsoleApi::base64encode(const std::string& str) {
    return base64encodeImpl(str);
}

void ConsoleApi::setPreferredMediaTypeHeader(std::map<std::string, std::string>& headers, const std::string& headerName, const std::vector<std::string>& contentTypes) {
    const std::string contentType = selectPreferredContentType(contentTypes);
    headers[headerName] = contentType;
}

